import{_ as e}from"./chunks/warning.DAc3S2yk.js";import{_ as n,o,c as t,a5 as s}from"./chunks/framework.CcrBcQWS.js";const u=JSON.parse('{"title":"Mechanical Safety","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/safety/mechanical-safety.md","filePath":"manual/safety/mechanical-safety.md","lastUpdated":1787021357000}'),i={name:"manual/safety/mechanical-safety.md"};function r(l,a,c,d,p,h){return o(),t("div",null,[...a[0]||(a[0]=[s('<h1 id="mechanical-safety" tabindex="-1">Mechanical Safety <a class="header-anchor" href="#mechanical-safety" aria-label="Permalink to &quot;Mechanical Safety&quot;">​</a></h1><p>Measures to prevent injury or damage from joints, legs, and drive components.</p><h2 id="motion-envelope-and-access" tabindex="-1">Motion envelope and access <a class="header-anchor" href="#motion-envelope-and-access" aria-label="Permalink to &quot;Motion envelope and access&quot;">​</a></h2><figure><img src="'+e+'" alt="Joint and leg motion range; pinch hazard" style="max-width:100%;width:min(420px, 100%);display:block;margin:0 auto;"><figcaption style="text-align:center;">[ During motion, keep hands, clothing, and cables clear of joints and legs. ]</figcaption></figure><p><strong>Red circles</strong> in the figure mark <strong>hazard zones</strong> with pinch and collision risk (around hip and leg joints). During handling, transport, and inspection, do not put fingers, clothing, cables, long hair, or jewelry into these zones.</p><div class="sb sb-warning"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">WARNING</p><p>1) Do not enter the motion envelope or put hands or body on the robot body or legs while it is moving-risk of pinch and collision.<br>2) If the robot falls or corrects posture, people or objects nearby can be struck-maintain sufficient clear space.</p></div></div><h2 id="locomotion-and-speed" tabindex="-1">Locomotion and speed <a class="header-anchor" href="#locomotion-and-speed" aria-label="Permalink to &quot;Locomotion and speed&quot;">​</a></h2><ul><li><strong>Walking</strong>: The RBQ moves on four legs. Observe <strong>speed, acceleration, and load limits</strong> in the manual and GUI. Speed changes take effect immediately; actual speed depends on floor friction, commands, balance correction, and faults.</li><li><strong>Stay within limits</strong>: Overload or excessive speed can cause failure or unstable motion. Collisions with objects can release large kinetic energy-apply safety settings suited to the environment.</li></ul><h2 id="joints-legs-and-pinch-risk" tabindex="-1">Joints, legs, and pinch risk <a class="header-anchor" href="#joints-legs-and-pinch-risk" aria-label="Permalink to &quot;Joints, legs, and pinch risk&quot;">​</a></h2><ul><li><strong>Pinch points</strong>: Mainly around <strong>hip</strong> and <strong>leg joints</strong>. During normal driving, hands usually cannot reach them, but during <strong>handling, transport, and inspection</strong>, keep fingers, clothing, cables, hair, and jewelry clear.</li><li><strong>If something is wrong</strong>: Stop immediately, trigger emergency stop, find the cause, then continue.</li></ul><h2 id="stairs-slopes-and-uneven-floors" tabindex="-1">Stairs, slopes, and uneven floors <a class="header-anchor" href="#stairs-slopes-and-uneven-floors" aria-label="Permalink to &quot;Stairs, slopes, and uneven floors&quot;">​</a></h2><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">CAUTION</p><p>On stairs or uneven surfaces the robot will try to adjust posture; you cannot eliminate all errors. Do <strong>not</strong> use sudden manual intervention or force the robot to stop. Limit approach distance and speed on stairs and slopes; keep about 2 m clearance if needed.</p></div></div><h2 id="installation-and-movement" tabindex="-1">Installation and movement <a class="header-anchor" href="#installation-and-movement" aria-label="Permalink to &quot;Installation and movement&quot;">​</a></h2><ul><li><strong>Flat floor</strong>: Use the robot on a flat, stable floor per specifications. It can fall on slopes or slippery surfaces.</li><li><strong>Handling and transport</strong>: Follow the procedures for moving, packing, and shipping. See <a href="/RBQ/nightly/manual/safety/handling-and-transportation.html">Handling and Transportation</a>.</li></ul>',14)])])}const f=n(i,[["render",r]]);export{u as __pageData,f as default};
